/** File > Save (Cmd+S) arrives from the native menu as this window event. */
export const SAVE_DOCUMENT_EVENT = 'airs-save-document'

/** How long typing pauses before the snapshot is protected on this Mac. */
export const PROTECT_DELAY_MS = 400
export const METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS']
const BODY_KINDS = ['text', 'json', 'form', 'multipart', 'file']

export const TEXTAREA = cn(
    'rounded-academy-md bg-academy-bg-inset border-academy-rule focus-visible:border-academy-accent-ring w-full border px-3.5 py-2.5',
    'text-academy-ink min-h-24 resize-y font-mono text-[13px] leading-snug'
)
export const SELECT = 'border-academy-rule rounded-academy-sm bg-academy-bg-inset min-h-11 border px-2'

const same = (a: Fields, b: Fields) =>
    a.method === b.method &&
    a.url === b.url &&
    a.headers === b.headers &&
    a.query === b.query &&
    a.body === b.body &&
    a.bodyKind === b.bodyKind &&
    a.settings === b.settings

export const requestName = (relative: string) => relative.split('/').pop()?.replace(/\.request\.toml$/, '') ?? relative

interface Props {
    initial: DocumentView
    call: WorkbenchCall
    schemas: string[]
    /** The document was closed by a choice made here. */
    onClosed: (id: string) => void
    /** Hands the workbench this document's close handle. */
    register?: (handle: EditorHandle) => void
    /** The active tenant context (Rust decides whether a request needs it). */
    context?: string | null
    /** This document's requests in flight. */
    running?: RunningView[]
    /** A tenant-credential change from this document awaiting review. */
    review?: SendReviewView | null
}

export interface EditorHandle {
    /**
     * Protects any edit not yet acknowledged; resolves whether everything
     * typed is now kept on this Mac. Closing a tab or the collection waits
     * for it.
     */
    flush: () => Promise<boolean>
    /** The operator chose to close without the latest edits. */
    abandon: () => void
}

/**
 * One request document. The editor text lives here (React owns immediate
 * input); Rust owns the baseline and revision. Save captures the fields the
 * editor holds at that moment, not a debounced copy; typing pauses protect
 * the snapshot on this Mac; a reply never overwrites newer typing.
 */
export function DocumentEditor({ initial, call, schemas, onClosed, register, context = null, running = [], review = null }: Props) {
    const ids = useId()
    const [doc, setDoc] = useState(initial)
    const [fields, setFields] = useState(initial.fields)
    const fieldsRef = useRef(initial.fields)
    const revisionRef = useRef(initial.revision)
    const idRef = useRef(initial.id)
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null)
    // Edit generations: every edit takes the next; Rust clears its
    // unprotected mark only for a snapshot covering its newest reported one.
    const editGen = useRef(0)
    const markedGen = useRef(0)
    const sentGen = useRef(0)
    const ackGen = useRef(0)
    const [status, setStatus] = useState('')
    const [saving, setSaving] = useState(false)
    const [preview, setPreview] = useState<Preview | null>(null)
    const [run, setRun] = useState<RunView | null>(null)
    const [sending, setSending] = useState(false)
    const [conflict, setConflict] = useState<'changed' | 'deleted' | 'interrupted' | null>(
        initial.interrupted ? 'interrupted' : initial.conflict
    )

    const adopt = useCallback((next: DocumentView, editor: Fields | null) => {
        setDoc(next)
        revisionRef.current = next.revision
        setConflict(next.interrupted ? 'interrupted' : next.conflict)
        if (editor !== null) {
            fieldsRef.current = editor
            setFields(editor)
        }
    }, [])

    const protect = useCallback((): Promise<boolean> => {
        timer.current = null
        const edit = editGen.current
        sentGen.current = Math.max(sentGen.current, edit)
        return call({ kind: 'protect', id: idRef.current, revision: revisionRef.current, fields: fieldsRef.current, edit }).then((r) => {
            if (r.kind === 'protected') {
                ackGen.current = Math.max(ackGen.current, edit)
                return true
            }
            setStatus(resultText(r) ?? '')
            return false
        })
    }, [call])

    // Protects whatever is not yet acknowledged (a pending pause, or a
    // protection that failed); resolves whether all typing is kept.
    const flush = useCallback((): Promise<boolean> => {
        const waiting = timer.current !== null
        if (timer.current !== null) clearTimeout(timer.current)
        if (waiting || editGen.current > ackGen.current) return protect()
        return Promise.resolve(true)
    }, [protect])

    const abandon = useCallback(() => {
        if (timer.current !== null) clearTimeout(timer.current)
        timer.current = null
        ackGen.current = editGen.current
    }, [])

    const registerRef = useRef(register)
    registerRef.current = register
    useEffect(() => {
        registerRef.current?.({ flush, abandon })
        // Leaving the document (another tab, another destination) protects
        // what was typed since the last pause; a later close waits for it.
        return () => {
            const left = flush()
            registerRef.current?.({ flush: () => left, abandon: () => {} })
        }
    }, [flush, abandon])

    const edit = (patch: Partial<Fields>) => {
        const next = { ...fieldsRef.current, ...patch }
        fieldsRef.current = next
        setFields(next)
        const generation = ++editGen.current
        // Re-armed whenever a submitted snapshot may have cleared the mark.
        if (markedGen.current <= sentGen.current) {
            markedGen.current = generation
            void call({ kind: 'editing', id: idRef.current, edit: generation })
        }
        if (timer.current !== null) clearTimeout(timer.current)
        timer.current = setTimeout(() => void protect(), PROTECT_DELAY_MS)
    }

    const reload = async () => {
        const r = await call({ kind: 'openRequest', relative: doc.relative })
        if (r.kind === 'document') adopt(r.document, r.document.fields)
    }

    const save = async () => {
        // The fields the editor holds now, whatever is still debouncing.
        const snapshot = fieldsRef.current
        const edit = editGen.current
        if (timer.current !== null) {
            clearTimeout(timer.current)
            timer.current = null
        }
        sentGen.current = Math.max(sentGen.current, edit)
        setSaving(true)
        setStatus('Saving…')
        const r = await call({ kind: 'save', id: idRef.current, revision: revisionRef.current, fields: snapshot, edit })
        setSaving(false)
        if (r.kind === 'saved' || r.kind === 'unchanged') {
            ackGen.current = Math.max(ackGen.current, edit)
            adopt(r.document, null)
            if (fieldsRef.current !== snapshot) {
                // Typed while saving: the newer text stays and is protected
                // against the new revision.
                setStatus('Saved. Edits made while saving are kept unsaved.')
                void protect()
            } else {
                setStatus(r.kind === 'saved' ? 'Saved' : 'No changes to save')
            }
            return
        }
        if (r.kind === 'saveRefused') {
            if (r.refusal.kind === 'conflict') setConflict('changed')
            if (r.refusal.kind === 'interrupted' || r.refusal.kind === 'io') setConflict('interrupted')
            setStatus(saveRefusalText(r.refusal))
            return
        }
        if (r.kind === 'refused' && r.problem.kind === 'stale') await reload()
        setStatus(resultText(r) ?? '')
    }

    const resolve = async (choice: 'useDisk' | 'keepMine') => {
        const r = await call({ kind: 'resolve', id: idRef.current, revision: revisionRef.current, fields: fieldsRef.current, choice })
        if (r.kind === 'closed') return onClosed(r.id)
        if (r.kind === 'document') {
            adopt(r.document, choice === 'useDisk' ? r.document.fields : null)
            setStatus(choice === 'useDisk' ? 'Using the files on disk. Your version was kept privately.' : 'Your edits now apply to the files on disk. Save to write them.')
            return
        }
        setStatus(resultText(r) ?? '')
    }

    const discard = async () => {
        const r = await call({ kind: 'discardDraft', id: idRef.current })
        if (r.kind === 'closed') return onClosed(r.id)
        if (r.kind === 'document') {
            ackGen.current = editGen.current
            adopt(r.document, r.document.fields)
            setStatus('Draft discarded')
            return
        }
        setStatus(resultText(r) ?? '')
    }

    const associate = async (schema: string) => {
        const r = await call({
            kind: 'associateSchema',
            id: idRef.current,
            revision: revisionRef.current,
            fields: fieldsRef.current,
            schema: schema === '' ? null : schema,
        })
        if (r.kind === 'document') adopt(r.document, null)
        else setStatus(resultText(r) ?? '')
    }

    // Send: the fields the editor holds now (never a debounced or saved
    // copy); Rust renders, admits and sends them.
    const sendNow = async (reviewId: string | null) => {
        const snapshot = fieldsRef.current
        setSending(true)
        setRun(null)
        setStatus(reviewId ? 'Waiting for your confirmation…' : 'Sending…')
        const r = await call(
            reviewId
                ? { kind: 'apply', review: reviewId, id: idRef.current, revision: revisionRef.current, fields: snapshot, context }
                : { kind: 'send', id: idRef.current, revision: revisionRef.current, fields: snapshot, context }
        )
        setSending(false)
        if (r.kind === 'ran') {
            setRun(r.run)
            setStatus('')
            return
        }
        if (r.kind === 'reviewRequired') {
            setStatus('This change to the tenant needs your review below.')
            return
        }
        if (r.kind === 'refused' && r.problem.kind === 'stale') await reload()
        setStatus(resultText(r) ?? '')
    }

    const showPreview = async () => {
        const r = await call({ kind: 'preview', id: idRef.current, fields: fieldsRef.current })
        if (r.kind === 'preview') setPreview(r.preview)
        else setStatus(resultText(r) ?? '')
    }

    // File > Save (Cmd+S) from the native menu saves this document.
    const saveRef = useRef(save)
    saveRef.current = save
    useEffect(() => {
        const onSave = () => void saveRef.current()
        window.addEventListener(SAVE_DOCUMENT_EVENT, onSave)
        return () => window.removeEventListener(SAVE_DOCUMENT_EVENT, onSave)
    }, [])

    const dirty = doc.new || doc.metadataDirty || !same(fields, doc.saved)
    const name = requestName(doc.relative)
    return (
        <form
            aria-label={`Request ${name}`}
            data-slot='workbench-document'
            className='flex flex-col gap-4'
            onSubmit={(e) => {
                e.preventDefault()
                void save()
            }}
            onKeyDown={(e) => {
                if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 's') {
                    e.preventDefault()
                    void save()
                }
            }}
        >
            <div className='flex flex-wrap items-baseline gap-2'>
                <h2 className='text-[17px] font-semibold'>{name}</h2>
                <span className='text-academy-ink-faint text-[12px]'>{doc.relative}</span>
                <span className='text-academy-ink-soft text-[12px]' data-slot='workbench-dirty'>
                    {doc.new ? 'New · not saved yet' : dirty ? 'Unsaved changes' : 'Saved'}
                </span>
            </div>
            {conflict ? (
                <Callout tone='warning' icon={AlertTriangle} role='alert' data-slot='workbench-conflict'>
                    <p className='text-academy-ink font-semibold'>
                        {conflict === 'deleted' ? 'Deleted on disk' : conflict === 'interrupted' ? 'Interrupted save' : 'Changed on disk'}
                    </p>
                    <p>
                        {conflict === 'interrupted'
                            ? 'An earlier save of this request did not finish. Choose which version to continue from; both are kept privately first.'
                            : 'The files changed since this request was opened. Choose which version to continue from; both are kept privately first.'}
                    </p>
                    <div className='mt-3 flex flex-wrap gap-2'>
                        <Button type='button' tier='secondary' onClick={() => void resolve('useDisk')}>
                            Use disk
                        </Button>
                        <Button type='button' tier='secondary' onClick={() => void resolve('keepMine')}>
                            Keep mine
                        </Button>
                    </div>
                </Callout>
            ) : null}
            {doc.recovered && !conflict ? (
                <Callout tone='info' icon={History} data-slot='workbench-recovered'>
                    <p className='text-academy-ink font-semibold'>Recovered draft</p>
                    <p>Unsaved changes from an earlier session were restored. Save to keep them in the collection.</p>
                    <Button type='button' tier='secondary' className='mt-3' onClick={() => void discard()}>
                        Discard draft
                    </Button>
                </Callout>
            ) : null}
            <div className='grid gap-3 sm:grid-cols-[10rem_1fr]'>
                <label className='flex flex-col gap-1 text-[13px] font-medium' htmlFor={`${ids}-method`}>
                    Method
                    <Input
                        id={`${ids}-method`}
                        list={`${ids}-methods`}
                        value={fields.method}
                        autoComplete='off'
                        spellCheck={false}
                        onChange={(e) => edit({ method: e.target.value })}
                    />
                    <datalist id={`${ids}-methods`}>
                        {METHODS.map((m) => (
                            <option key={m} value={m} />
                        ))}
                    </datalist>
                </label>
                <label className='flex flex-col gap-1 text-[13px] font-medium' htmlFor={`${ids}-url`}>
                    URL
                    <Input id={`${ids}-url`} value={fields.url} autoComplete='off' spellCheck={false} onChange={(e) => edit({ url: e.target.value })} />
                </label>
            </div>
            <label className='flex flex-col gap-1 text-[13px] font-medium' htmlFor={`${ids}-query`}>
                Params
                <textarea
                    id={`${ids}-query`}
                    className={TEXTAREA}
                    value={fields.query}
                    spellCheck={false}
                    aria-describedby={`${ids}-rows`}
                    onChange={(e) => edit({ query: e.target.value })}
                />
            </label>
            <label className='flex flex-col gap-1 text-[13px] font-medium' htmlFor={`${ids}-headers`}>
                Headers
                <textarea
                    id={`${ids}-headers`}
                    className={TEXTAREA}
                    value={fields.headers}
                    spellCheck={false}
                    aria-describedby={`${ids}-rows`}
                    onChange={(e) => edit({ headers: e.target.value })}
                />
            </label>
            <p id={`${ids}-rows`} className='text-academy-ink-faint -mt-2 text-[12px]'>
                One row per line: name=value for params, Name: value for headers. Start a row with "# " to disable it.
            </p>
            <div className='flex flex-col gap-1'>
                <label className='flex flex-col gap-1 text-[13px] font-medium' htmlFor={`${ids}-kind`}>
                    Body kind
                    <select id={`${ids}-kind`} className={SELECT} value={fields.bodyKind} onChange={(e) => edit({ bodyKind: e.target.value })}>
                        {BODY_KINDS.map((k) => (
                            <option key={k} value={k}>
                                {k}
                            </option>
                        ))}
                    </select>
                </label>
                <label className='flex flex-col gap-1 text-[13px] font-medium' htmlFor={`${ids}-body`}>
                    Body
                    <textarea
                        id={`${ids}-body`}
                        className={TEXTAREA}
                        value={fields.body}
                        spellCheck={false}
                        readOnly={!doc.bodyEditable}
                        onChange={(e) => edit({ body: e.target.value })}
                    />
                </label>
                {!doc.bodyEditable ? (
                    <p className='text-academy-ink-faint text-[12px]'>This body is not text or is larger than 4 MiB; it is kept exactly as it is.</p>
                ) : null}
            </div>
            <label className='flex flex-col gap-1 text-[13px] font-medium' htmlFor={`${ids}-settings`}>
                Auth and variables (TOML)
                <textarea
                    id={`${ids}-settings`}
                    className={TEXTAREA}
                    value={fields.settings}
                    spellCheck={false}
                    aria-describedby={`${ids}-settings-hint`}
                    onChange={(e) => edit({ settings: e.target.value })}
                />
            </label>
            <p id={`${ids}-settings-hint`} className='text-academy-ink-faint -mt-2 text-[12px]'>
                [auth] names secret references (kind none, basic, bearer, api-key or oauth2); [variables] holds strings or {'{ secret = "reference" }'}. Values are entered in Secrets, never here.
            </p>
            <label className='flex flex-col gap-1 text-[13px] font-medium'>
                Schema
                <select className={SELECT} value={doc.schema ?? ''} onChange={(e) => void associate(e.target.value)}>
                    <option value=''>No schema</option>
                    {schemas.map((s) => (
                        <option key={s} value={s}>
                            {s}
                        </option>
                    ))}
                </select>
            </label>
            <div className='flex flex-wrap items-center gap-2'>
                <Button type='submit' tier='primary' disabled={saving}>
                    <Save aria-hidden className='size-4' />
                    Save
                </Button>
                <Button type='button' tier='primary' disabled={sending} onClick={() => void sendNow(null)}>
                    <Send aria-hidden className='size-4' />
                    Send
                </Button>
                <Button type='button' tier='secondary' onClick={() => void showPreview()}>
                    Preview
                </Button>
                {dirty && !doc.new && !doc.recovered ? (
                    <Button type='button' tier='secondary' onClick={() => void discard()}>
                        Discard changes
                    </Button>
                ) : null}
                <p role='status' aria-live='polite' className='text-academy-ink-soft text-[13px]' data-slot='workbench-save-status'>
                    {status}
                </p>
            </div>
            {running.map((r) => (
                <Running key={r.run} running={r} call={call} />
            ))}
            {review ? (
                <ReviewPanel
                    review={review}
                    onApply={() => void sendNow(review.review)}
                    onDismiss={() => void call({ kind: 'dismissReview' }).then(() => setStatus(''))}
                />
            ) : null}
            {run ? <RunPanel run={run} call={call} /> : null}
            {preview ? <PreviewPanel preview={preview} /> : null}
        </form>
    )
}

function PreviewPanel({ preview }: { preview: Preview }) {
    return (
        <section aria-label='Request preview' data-slot='workbench-preview' className='border-academy-rule rounded-academy-md flex flex-col gap-2 border p-4 text-[13px]'>
            <h3 className='text-[14px] font-semibold'>Preview (nothing is sent)</h3>
            <p className='font-mono break-all'>{`${preview.method} ${preview.url}`}</p>
            {preview.query.length ? <p className='font-mono break-all'>Params: {preview.query.map(([n, v]) => `${n}=${v}`).join('&')}</p> : null}
            {preview.headers.map(([n, v], i) => (
                <p key={i} className='font-mono break-all'>
                    {`${n}: ${v}`}
                </p>
            ))}
            {preview.body ? <pre className='bg-academy-bg-inset overflow-auto p-2 font-mono text-[12px] whitespace-pre-wrap'>{preview.body}</pre> : null}
            {preview.auth && preview.auth !== 'none' ? <p>{`Authentication: ${preview.auth}`}</p> : null}
            {preview.unresolved.length ? <p role='alert'>{`Unresolved variables: ${preview.unresolved.join(', ')}`}</p> : null}
            {preview.missingSecrets.length ? <p role='alert'>{`Secrets without a value on this Mac: ${preview.missingSecrets.join(', ')}`}</p> : null}
            {preview.problem ? <p role='alert'>{fieldText(preview.problem)}</p> : null}
            {preview.jsonWarning ? <p>The JSON body does not parse; it is kept exactly as typed.</p> : null}
            <p className='text-academy-ink-faint text-[12px]'>Secret values are masked. Send prepares the request again from what you have typed.</p>
        </section>
    )
}

}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_body_not_yet_written_is_owned_by_its_case_folded_name() {
        let dir = crate::workbench::testdir::Dir::new();
        let root = dir.path().join("c");
        std::fs::create_dir_all(root.join("items")).expect("fixture");
        std::fs::write(
            root.join("collection.toml"),
            "format_version = 1\nid = \"coll\"\nname = \"Coll\"\n",
        )
        .expect("fixture");
        // An invalid request (its body is missing) still reserves the name.
        std::fs::write(
            root.join("items/ghost.request.toml"),
            "format_version = 1\nid = \"ghost\"\nmethod = \"GET\"\nurl = \"https://g.example/\"\nbody = \"items/ghost.body.txt\"\n",
        )
        .expect("fixture");
        let catalog = project::discover(&root).expect("fixture");
        let me = "items/new.request.toml";
        assert!(shared(&root, &catalog, me, "items/ghost.body.txt"));
        assert!(shared(&root, &catalog, me, "items/GHOST.body.txt"));
        assert!(shared(&root, &catalog, me, "Collection.TOML"));
        assert!(shared(&root, &catalog, me, "items/New.Request.toml"));
        assert!(!shared(&root, &catalog, me, "items/free.body.txt"));
    }

    #[test]
    fn rows_round_trip_and_report_their_line() {
        assert_eq!(
            header_rows("A: 1\n\n# B: two words ").expect("fixture"),
            vec![
                Row {
                    name: "A".into(),
                    value: "1".into(),
                    enabled: true
                },
                Row {
                    name: "B".into(),
                    value: "two words".into(),
                    enabled: false
                },
            ]
        );
        assert_eq!(
            header_rows("A: 1\nbroken").expect_err("fixture"),
            FieldProblem {
                field: FieldName::Headers,
                line: Some(2)
            }
        );
        assert_eq!(
            query_rows("q= spaced ").expect("fixture")[0].value,
            " spaced "
        );
        assert!(query_rows("=v").is_err());
    }

    #[test]
    fn settings_hold_references_never_credentials() {
        assert!(settings_ok("[auth]\nkind = \"bearer\"\nsecret = \"token\"\n").is_some());
        assert!(settings_ok("[variables]\nhost = \"x\"\nkey = { secret = \"k\" }\n").is_some());
        assert!(settings_ok("[auth]\nkind = \"bearer\"\ntoken = \"abc\"\n").is_none());
        assert!(settings_ok("[auth]\nkind = \"digest\"\n").is_none());
        assert!(settings_ok("[auth]\nsecret = \"bad ref\"\n").is_none());
        assert!(settings_ok("[variables]\nkey = { secret = \"k\", value = \"v\" }\n").is_none());
        assert!(settings_ok("[environment]\n").is_none());
        assert!(settings_ok("[auth\n").is_none());
    }

    #[test]
    fn checks_name_the_field_that_cannot_be_written() {
        let ok = Fields::default();
        assert_eq!(check(&ok), Ok(()));
        let field = |f: Fields| check(&f).expect_err("fixture").field;
        assert_eq!(
            field(Fields {
                method: "G T".into(),
                ..ok.clone()
            }),
            FieldName::Method
        );
        assert_eq!(
            field(Fields {
                url: " ".into(),
                ..ok.clone()
            }),
            FieldName::Url
        );
        assert_eq!(
            field(Fields {
                body_kind: "xml".into(),
                ..ok.clone()
            }),
            FieldName::BodyKind
        );
        assert_eq!(
            field(Fields {
                body_kind: "multipart".into(),
                body: "[[parts]]\nvalue = \"x\"\n".into(),
                ..ok.clone()
            }),
            FieldName::Body
        );
        assert_eq!(
            check(&Fields {
                body_kind: "json".into(),
                body: "{not json".into(),
                ..ok.clone()
            }),
            Ok(())
        );
    }

    #[test]
    fn edits_keep_comments_extensions_and_line_endings() {
        let syntax = "# kept\r\nformat_version = 1\r\nid = \"a\"\r\nmethod = \"GET\" # verb\r\nurl = \"https://a/\"\r\nx-ext = 3\r\n\r\n[[headers]]\r\nname = \"A\"\r\nvalue = \"1\"\r\nnote = \"kept\"\r\n";
        let doc = Document {
            id: "a".into(),
            relative: "a.request.toml".into(),
            syntax: syntax.into(),
            baseline: Baseline::new(),
            saved: Fields {
                method: "GET".into(),
                url: "https://a/".into(),
                headers: "A: 1".into(),
                ..Fields::default()
            },
            new: false,
            body_editable: true,
            metadata_dirty: false,
        };
        let fields = Fields {
            method: "POST".into(),
            headers: "B: 2\nA: 1".into(),
            ..doc.saved.clone()
        };
        let edited = doc.edited_syntax(&fields).expect("fixture");
        assert!(edited.starts_with("# kept\r\n"));
        assert!(edited.contains("method = \"POST\" # verb\r\n"));
        assert!(edited.contains("x-ext = 3"));
        assert!(edited.contains("note = \"kept\""));
        assert!(!edited.replace("\r\n", "").contains('\n'));
        assert!(edited.find("\"B\"").expect("fixture") < edited.find("\"A\"").expect("fixture"));
    }
}
//! v1's portable project format (C14): a collection is a folder holding
//! `collection.toml` (`format_version = 1`, `id`, `name`, optional
//! `[variables]`), `*.request.toml` request files with their body sidecars,
//! shared `environments/*.toml` and schema text files. Discovery is
//! read-only and bounded; it never follows symbolic links, enters `.git` or
//! a nested collection, and reports (never repairs) invalid or duplicate
//! identities. Writes are atomic and stay inside the collection.

use std::collections::BTreeMap;
use std::io::{Read, Write};
use std::path::{Component, Path, PathBuf};

use serde::Serialize;
use toml_edit::{DocumentMut, Item};
use ts_rs::TS;

/// Request and collection metadata files (v1: 1 MiB each).
pub const METADATA_BYTES: usize = 1024 * 1024;
/// Request files a collection may hold (beyond: incomplete inventory).
pub const MAX_REQUESTS: usize = 2_000;
/// Directory entries discovery reads before giving up (incomplete).
pub const MAX_ENTRIES: usize = 20_000;
/// Folder nesting discovery follows.
pub const MAX_DEPTH: usize = 24;
/// Collection-relative paths (bytes).
pub const MAX_PATH: usize = 512;
pub const REQUEST_SUFFIX: &str = ".request.toml";

/// Why a project operation was refused (sanitized; never file contents).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
pub enum ProjectProblem {
    /// The folder holds no readable `collection.toml` of format 1.
    NotCollection,
    /// A path is absolute, escapes the collection, is hidden or is too long.
    BadPath,
    /// Something already exists at the destination.
    Exists,
    /// A new collection must be created inside a Git repository (v1).
    NotInRepository,
    /// The inventory is incomplete; fix its issues before changing files.
    Incomplete,
    /// The request is invalid, missing or shares its ID with another.
    Missing,
    /// A file exceeds its limit.
    TooLarge,
    /// The file could not be read or written.
    Io,
}

/// One discovered request (from its file's metadata).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct RequestEntry {
    /// Collection-relative, `/`-separated.
    pub relative: String,
    pub id: String,
    /// Navigator text, abbreviated; an opened document reads its own
    /// metadata instead.
    pub method: String,
    pub url: String,
}

/// Why a candidate file was left out of the inventory.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
pub enum IssueKind {
    /// A symbolic link (never followed).
    Link,
    /// The file could not be read, parsed or validated.
    Invalid,
    /// Its ID is also used by another request; every copy is left out.
    Duplicate,
    /// Its schema association names no readable schema file.
    Schema,
    /// The name is not valid UTF-8 or is too long.
    Name,
    /// Discovery stopped at a limit (requests, entries or depth).
    Limit,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
pub struct Issue {
    pub relative: String,
    pub kind: IssueKind,
}

/// A collection's read-only inventory.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Catalog {
    pub root: PathBuf,
    pub id: String,
    pub name: String,
    pub requests: Vec<RequestEntry>,
    /// Folders (collection-relative), including empty ones.
    pub folders: Vec<String>,
    /// Shared environment names (`environments/<name>.toml`).
    pub environments: Vec<String>,
    /// Schema files (`.json`, `.yaml`, `.yml`) found anywhere.
    pub schemas: Vec<String>,
    pub issues: Vec<Issue>,
    /// False when any candidate could not be read or validated, or a limit
    /// was reached: no complete identity inventory may be assumed.
    pub complete: bool,
    /// Secret references named by the collection defaults, shared
    /// environments and request files (never values).
    pub references: std::collections::BTreeSet<String>,
    /// Every body file named by a parseable request file (duplicates and
    /// invalid requests included) and the request files naming it: the
    /// ownership evidence a body write is checked against.
    pub bodies: BTreeMap<String, std::collections::BTreeSet<String>>,
}

pub(crate) fn valid_id(id: &str) -> bool {
    !id.is_empty()
        && id.len() <= 128
        && id
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
}

/// A fresh 32-hex-digit identity (as v1's).
pub fn new_id() -> Option<String> {
    let mut entropy = [0u8; 16];
    getrandom::fill(&mut entropy).ok()?;
    Some(hex::encode(entropy))
}

/// A collection-relative path as written in project files: `/`-separated
/// normal components, no `..`, `.`, empty, backslash, NUL or `.git`
/// component. `creating` also refuses hidden (dot-prefixed) names.
pub fn relative_path(text: &str, creating: bool) -> Option<PathBuf> {
    if text.is_empty() || text.len() > MAX_PATH || text.contains(['\\', '\0']) {
        return None;
    }
    let mut path = PathBuf::new();
    for part in text.split('/') {
        if part.is_empty()
            || part == "."
            || part == ".."
            || part == ".git"
            || (creating && part.starts_with('.'))
            || part.len() > 255
        {
            return None;
        }
        path.push(part);
    }
    if path.components().all(|c| matches!(c, Component::Normal(_))) {
        Some(path)
    } else {
        None
    }
}

fn slash(path: &Path) -> Option<String> {
    let parts: Option<Vec<&str>> = path.components().map(|c| c.as_os_str().to_str()).collect();
    parts.map(|p| p.join("/"))
}

/// Where `relative` lives in `root`, refusing any existing component that
/// is a symbolic link, `.git` or a nested collection. The destination need
/// not exist.
pub fn destination(root: &Path, relative: &Path) -> Result<PathBuf, ProjectProblem> {
    let mut path = root.to_path_buf();
    let count = relative.components().count();
    for (index, part) in relative.components().enumerate() {
        let Component::Normal(name) = part else {
            return Err(ProjectProblem::BadPath);
        };
        if name == ".git" {
            return Err(ProjectProblem::BadPath);
        }
        path.push(name);
        match std::fs::symlink_metadata(&path) {
            Ok(meta) if meta.file_type().is_symlink() => return Err(ProjectProblem::BadPath),
            Ok(meta) if meta.is_dir() && index + 1 < count => {
                if path.join("collection.toml").exists() {
                    return Err(ProjectProblem::BadPath);
                }
            }
            Ok(_) => {}
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(_) => return Err(ProjectProblem::Io),
        }
    }
    Ok(path)
}

/// Reads at most `limit` bytes of a regular file (`TooLarge` beyond).
pub fn read_bounded(path: &Path, limit: usize) -> Result<Vec<u8>, ProjectProblem> {
    let meta = std::fs::symlink_metadata(path).map_err(|_| ProjectProblem::Io)?;
    if !meta.is_file() {
        return Err(ProjectProblem::Io);
    }
    let mut bytes = Vec::new();
    std::fs::File::open(path)
        .and_then(|f| f.take(limit as u64 + 1).read_to_end(&mut bytes))
        .map_err(|_| ProjectProblem::Io)?;
    if bytes.len() > limit {
        return Err(ProjectProblem::TooLarge);
    }
    Ok(bytes)
}

/// The bytes at `relative`, `None` when absent.
pub fn read_optional(
    root: &Path,
    relative: &Path,
    limit: usize,
) -> Result<Option<Vec<u8>>, ProjectProblem> {
    let path = destination(root, relative)?;
    match std::fs::symlink_metadata(&path) {
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(_) => Err(ProjectProblem::Io),
        Ok(_) => read_bounded(&path, limit).map(Some),
    }
}

pub(crate) fn parse_metadata(bytes: &[u8]) -> Option<DocumentMut> {
    std::str::from_utf8(bytes).ok()?.parse().ok()
}

pub(crate) fn format_one(doc: &DocumentMut) -> bool {
    doc.get("format_version").and_then(Item::as_integer) == Some(1)
}

pub(crate) fn string<'a>(doc: &'a DocumentMut, key: &str) -> Option<&'a str> {
    doc.get(key)
        .and_then(Item::as_str)
        .filter(|s| !s.is_empty())
}

/// Replaces `relative` atomically (temporary file, fsync, rename, fsync of
/// the folder), creating missing folders inside the collection. An existing
/// file keeps its permissions.
pub fn replace(root: &Path, relative: &Path, bytes: &[u8]) -> Result<(), ProjectProblem> {
    let path = destination(root, relative)?;
    let dir = path.parent().ok_or(ProjectProblem::BadPath)?;
    std::fs::create_dir_all(dir).map_err(|_| ProjectProblem::Io)?;
    // Folders created just now are checked again (no link raced in).
    destination(root, relative)?;
    let mut suffix = [0u8; 8];
    getrandom::fill(&mut suffix).map_err(|_| ProjectProblem::Io)?;
    let temp = dir.join(format!(".{}.wbtmp", hex::encode(suffix)));
    let written = (|| -> std::io::Result<()> {
        let mut file = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temp)?;
        if let Ok(meta) = std::fs::metadata(&path) {
            file.set_permissions(meta.permissions())?;
        }
        file.write_all(bytes)?;
        file.sync_all()?;
        std::fs::rename(&temp, &path)?;
        std::fs::File::open(dir)?.sync_all()
    })();
    if written.is_err() {
        let _ = std::fs::remove_file(&temp);
    }
    written.map_err(|_| ProjectProblem::Io)
}

/// Removes `relative` (absent is fine).
pub fn remove(root: &Path, relative: &Path) -> Result<(), ProjectProblem> {
    let path = destination(root, relative)?;
    match std::fs::remove_file(&path) {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(_) => Err(ProjectProblem::Io),
    }
}

/// Reads a collection's manifest: (id, name).
pub fn manifest(root: &Path) -> Result<(String, String), ProjectProblem> {
    let bytes = read_optional(root, Path::new("collection.toml"), METADATA_BYTES)
        .map_err(|_| ProjectProblem::NotCollection)?
        .ok_or(ProjectProblem::NotCollection)?;
    let doc = parse_metadata(&bytes).ok_or(ProjectProblem::NotCollection)?;
    if !format_one(&doc) {
        return Err(ProjectProblem::NotCollection);
    }
    let id = string(&doc, "id")
        .filter(|id| valid_id(id))
        .ok_or(ProjectProblem::NotCollection)?;
    let name = string(&doc, "name").unwrap_or(id);
    Ok((id.to_owned(), name.chars().take(128).collect()))
}

pub(crate) fn schema_file(name: &str) -> bool {
    [".json", ".yaml", ".yml"]
        .iter()
        .any(|ext| name.len() > ext.len() && name.ends_with(ext))
}

/// Opens a collection and discovers its inventory without writing.
pub fn discover(root: &Path) -> Result<Catalog, ProjectProblem> {
    let root = root
        .canonicalize()
        .map_err(|_| ProjectProblem::NotCollection)?;
    let (id, name) = manifest(&root)?;
    let mut catalog = Catalog {
        root,
        id,
        name,
        requests: Vec::new(),
        folders: Vec::new(),
        environments: Vec::new(),
        schemas: Vec::new(),
        issues: Vec::new(),
        complete: true,
        references: std::collections::BTreeSet::new(),
        bodies: BTreeMap::new(),
    };
    if let Ok(Some(bytes)) =
        read_optional(&catalog.root, Path::new("collection.toml"), METADATA_BYTES)
        && let Some(doc) = parse_metadata(&bytes)
    {
        super::environments::references_in(&doc, &mut catalog.references);
    }
    let mut walk = Walk {
        identities: BTreeMap::new(),
        entries: 0,
    };
    scan(&mut catalog, &mut walk, Path::new(""), 0);
    for (id, paths) in walk.identities {
        if paths.len() > 1 {
            catalog.requests.retain(|r| r.id != id);
            for relative in paths {
                catalog.issues.push(Issue {
                    relative,
                    kind: IssueKind::Duplicate,
                });
            }
        }
    }
    catalog.requests.sort_by(|a, b| a.relative.cmp(&b.relative));
    catalog.folders.sort();
    catalog.schemas.sort();
    catalog.environments.sort();
    catalog.issues.sort_by(|a, b| a.relative.cmp(&b.relative));
    Ok(catalog)
}

struct Walk {
    identities: BTreeMap<String, Vec<String>>,
    entries: usize,
}

fn limit(catalog: &mut Catalog, relative: String) {
    catalog.complete = false;
    catalog.issues.push(Issue {
        relative,
        kind: IssueKind::Limit,
    });
}

fn scan(catalog: &mut Catalog, walk: &mut Walk, directory: &Path, depth: usize) {
    let Ok(read) = std::fs::read_dir(catalog.root.join(directory)) else {
        catalog.complete = false;
        catalog.issues.push(Issue {
            relative: slash(directory).unwrap_or_default(),
            kind: IssueKind::Invalid,
        });
        return;
    };
    let mut entries: Vec<_> = read.filter_map(Result::ok).collect();
    entries.sort_by_key(|e| e.file_name());
    if let Some(folder) = slash(directory).filter(|f| !f.is_empty()) {
        catalog.folders.push(folder);
    }
    for entry in entries {
        walk.entries += 1;
        if walk.entries > MAX_ENTRIES {
            limit(catalog, slash(directory).unwrap_or_default());
            return;
        }
        let relative = directory.join(entry.file_name());
        let Some(text) = slash(&relative).filter(|t| t.len() <= MAX_PATH) else {
            catalog.complete = false;
            catalog.issues.push(Issue {
                relative: relative.to_string_lossy().chars().take(MAX_PATH).collect(),
                kind: IssueKind::Name,
            });
            continue;
        };
        let Ok(kind) = entry.file_type() else {
            catalog.complete = false;
            catalog.issues.push(Issue {
                relative: text,
                kind: IssueKind::Invalid,
            });
            continue;
        };
        let name = entry.file_name().to_string_lossy().into_owned();
        if kind.is_symlink() {
            catalog.issues.push(Issue {
                relative: text,
                kind: IssueKind::Link,
            });
        } else if kind.is_dir() {
            if name == ".git" || entry.path().join("collection.toml").exists() {
                continue;
            }
            if depth + 1 > MAX_DEPTH {
                limit(catalog, text);
                continue;
            }
            scan(catalog, walk, &relative, depth + 1);
        } else if kind.is_file() && name.ends_with(REQUEST_SUFFIX) {
            if catalog.requests.len() >= MAX_REQUESTS {
                limit(catalog, text);
                continue;
            }
            request(catalog, walk, &relative, text);
        } else if kind.is_file() {
            if directory == Path::new("environments")
                && let Some(env) = name.strip_suffix(".toml")
                && super::environments::valid_name(env)
            {
                if let Some(doc) =
                    read_bounded(&entry.path(), super::environments::ENVIRONMENT_BYTES)
                        .ok()
                        .and_then(|b| parse_metadata(&b))
                {
                    super::environments::references_in(&doc, &mut catalog.references);
                }
                catalog.environments.push(env.to_owned());
            } else if schema_file(&name) {
                catalog.schemas.push(text);
            }
        }
    }
}

fn request(catalog: &mut Catalog, walk: &mut Walk, relative: &Path, text: String) {
    let invalid = |catalog: &mut Catalog, text: String| {
        catalog.complete = false;
        catalog.issues.push(Issue {
            relative: text,
            kind: IssueKind::Invalid,
        });
    };
    let Some(doc) = read_bounded(&catalog.root.join(relative), METADATA_BYTES)
        .ok()
        .and_then(|b| parse_metadata(&b))
    else {
        return invalid(catalog, text);
    };
    super::environments::references_in(&doc, &mut catalog.references);
    if let Some(body) = doc.get("body").and_then(Item::as_str) {
        catalog
            .bodies
            .entry(body.to_owned())
            .or_default()
            .insert(text.clone());
    }
    // Even an invalid request reserves its parseable identity, so a valid
    // copy cannot silently absorb it.
    if let Some(id) = string(&doc, "id") {
        walk.identities
            .entry(id.to_owned())
            .or_default()
            .push(text.clone());
    }
    let id = string(&doc, "id").filter(|id| valid_id(id));
    let method = string(&doc, "method");
    let url = string(&doc, "url");
    let (Some(id), Some(method), Some(url), true) = (id, method, url, format_one(&doc)) else {
        return invalid(catalog, text);
    };
    if let Some(body) = doc.get("body") {
        let ok = body
            .as_str()
            .and_then(|b| relative_path(b, false))
            .and_then(|b| destination(&catalog.root, &b).ok())
            .is_some_and(|p| std::fs::symlink_metadata(&p).is_ok_and(|m| m.is_file()));
        if !ok {
            return invalid(catalog, text);
        }
    }
    if let Some(schema) = doc.get("schema") {
        let ok = schema
            .as_str()
            .and_then(|s| relative_path(s, false))
            .and_then(|s| destination(&catalog.root, &s).ok())
            .is_some_and(|p| std::fs::symlink_metadata(&p).is_ok_and(|m| m.is_file()));
        if !ok {
            // A separately owned schema cannot obscure the request's
            // identity or block editing.
            catalog.issues.push(Issue {
                relative: text.clone(),
                kind: IssueKind::Schema,
            });
        }
    }
    catalog.requests.push(RequestEntry {
        relative: text,
        id: id.to_owned(),
        method: method.chars().take(32).collect(),
        url: url.chars().take(2048).collect(),
    });
}

/// Creates a new collection folder `path` (v1: inside an existing Git
/// repository) with a fresh identity and its folder name.
pub fn create_collection(path: &Path) -> Result<String, ProjectProblem> {
    if path.exists() {
        return Err(ProjectProblem::Exists);
    }
    let parent = path
        .parent()
        .and_then(|p| p.canonicalize().ok())
        .ok_or(ProjectProblem::BadPath)?;
    if !parent.ancestors().any(|p| p.join(".git").exists()) {
        return Err(ProjectProblem::NotInRepository);
    }
    let name = path
        .file_name()
        .and_then(|n| n.to_str())
        .filter(|n| !n.starts_with('.') && !n.is_empty())
        .ok_or(ProjectProblem::BadPath)?
        .to_owned();
    let id = new_id().ok_or(ProjectProblem::Io)?;
    std::fs::create_dir(path).map_err(|_| ProjectProblem::Io)?;
    let root = path.canonicalize().map_err(|_| ProjectProblem::Io)?;
    let mut doc = DocumentMut::new();
    doc["format_version"] = toml_edit::value(1);
    doc["id"] = toml_edit::value(id.as_str());
    doc["name"] = toml_edit::value(name.as_str());
    replace(
        &root,
        Path::new("collection.toml"),
        doc.to_string().as_bytes(),
    )?;
    Ok(id)
}

/// Creates an (empty) folder inside the collection.
pub fn create_folder(catalog: &Catalog, relative: &str) -> Result<(), ProjectProblem> {
    if !catalog.complete {
        return Err(ProjectProblem::Incomplete);
    }
    let rel = relative_path(relative, true).ok_or(ProjectProblem::BadPath)?;
    let path = destination(&catalog.root, &rel)?;
    if path.exists() {
        return Err(ProjectProblem::Exists);
    }
    std::fs::create_dir_all(&path).map_err(|_| ProjectProblem::Io)?;
    destination(&catalog.root, &rel).map(|_| ())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::workbench::testdir::Dir;

    fn collection() -> (Dir, PathBuf) {
        let dir = Dir::new();
        let root = dir.path().join("c");
        std::fs::create_dir(&root).expect("fixture");
        std::fs::write(
            root.join("collection.toml"),
            "format_version = 1\nid = \"coll\"\nname = \"Coll\"\n",
        )
        .expect("fixture");
        (dir, root)
    }

    #[test]
    fn paths_stay_inside_and_visible() {
        assert!(relative_path("a/b.request.toml", true).is_some());
        for bad in [
            "", "/a", "../a", "a/../b", "a//b", ".hidden", "a\\b", ".git/x",
        ] {
            assert!(relative_path(bad, true).is_none(), "{bad}");
        }
        assert!(relative_path(".hidden/x", false).is_some());
        // Reading allows hidden names, so `..` and `.` must be refused on
        // their own there.
        for bad in ["../a", "a/../b", "a/..", "./a", "a/./b"] {
            assert!(relative_path(bad, false).is_none(), "{bad}");
        }
        assert!(relative_path(&"a".repeat(MAX_PATH + 1), false).is_none());
    }

    #[test]
    fn discovery_reports_duplicates_links_and_invalid_files() {
        let (_d, root) = collection();
        let req = |id: &str| {
            format!(
                "format_version = 1\nid = \"{id}\"\nmethod = \"GET\"\nurl = \"https://example.com/\"\n"
            )
        };
        std::fs::create_dir(root.join("f")).expect("fixture");
        std::fs::write(root.join("a.request.toml"), req("one")).expect("fixture");
        std::fs::write(root.join("f/b.request.toml"), req("one")).expect("fixture");
        std::fs::write(root.join("f/c.request.toml"), req("two")).expect("fixture");
        std::fs::write(root.join("bad.request.toml"), "not = [toml").expect("fixture");
        std::os::unix::fs::symlink(root.join("a.request.toml"), root.join("l.request.toml"))
            .expect("fixture");
        std::fs::create_dir(root.join(".git")).expect("fixture");
        std::fs::write(root.join(".git/x.request.toml"), req("three")).expect("fixture");
        std::fs::create_dir_all(root.join("nested")).expect("fixture");
        std::fs::write(
            root.join("nested/collection.toml"),
            "format_version = 1\nid = \"n\"\n",
        )
        .expect("fixture");
        std::fs::write(root.join("nested/n.request.toml"), req("four")).expect("fixture");
        std::fs::create_dir(root.join("environments")).expect("fixture");
        std::fs::write(root.join("environments/dev.toml"), "format_version = 1\n")
            .expect("fixture");
        std::fs::write(root.join("f/api.yaml"), "openapi: 3.1.0\n").expect("fixture");
        let catalog = discover(&root).expect("fixture");
        assert_eq!(catalog.id, "coll");
        assert_eq!(
            catalog
                .requests
                .iter()
                .map(|r| r.relative.as_str())
                .collect::<Vec<_>>(),
            ["f/c.request.toml"]
        );
        assert!(!catalog.complete);
        let kinds: Vec<_> = catalog
            .issues
            .iter()
            .map(|i| (i.relative.as_str(), i.kind))
            .collect();
        assert!(kinds.contains(&("a.request.toml", IssueKind::Duplicate)));
        assert!(kinds.contains(&("f/b.request.toml", IssueKind::Duplicate)));
        assert!(kinds.contains(&("bad.request.toml", IssueKind::Invalid)));
        assert!(kinds.contains(&("l.request.toml", IssueKind::Link)));
        assert_eq!(catalog.environments, ["dev"]);
        assert_eq!(catalog.schemas, ["f/api.yaml"]);
        assert_eq!(catalog.folders, ["environments", "f"]);
    }

    #[test]
    fn writes_refuse_links_git_and_nested_collections() {
        let (d, root) = collection();
        let outside = d.path().join("outside");
        std::fs::create_dir(&outside).expect("fixture");
        std::os::unix::fs::symlink(&outside, root.join("link")).expect("fixture");
        assert_eq!(
            replace(&root, Path::new("link/x.txt"), b"x"),
            Err(ProjectProblem::BadPath)
        );
        assert!(!outside.join("x.txt").exists());
        std::fs::create_dir_all(root.join("n")).expect("fixture");
        std::fs::write(root.join("n/collection.toml"), "").expect("fixture");
        assert_eq!(
            replace(&root, Path::new("n/x.txt"), b"x"),
            Err(ProjectProblem::BadPath)
        );
        replace(&root, Path::new("new/deep/x.txt"), b"x").expect("fixture");
        assert_eq!(
            std::fs::read(root.join("new/deep/x.txt")).expect("fixture"),
            b"x"
        );
    }

    #[test]
    fn collections_are_created_inside_repositories_only() {
        let d = Dir::new();
        assert_eq!(
            create_collection(&d.path().join("c")),
            Err(ProjectProblem::NotInRepository)
        );
        std::fs::create_dir(d.path().join(".git")).expect("fixture");
