                if p.is_dir() {
                    stack.push(p)
                } else {
                    paths.push(p)
                }
            }
        }
        paths.sort();
        let mut h = Sha256::new();
        for p in paths {
            h.update(p.to_string_lossy().as_bytes());
            h.update(std::fs::read(&p).expect("fixture"));
        }
